from pathlib import Path
import json
D=Path(__file__).resolve().parent
def get(k):return json.loads((D/k).read_bytes())
def fmt(x):return ('%.2f'%x).replace('.',',')
def interval(c,k):return fmt(c['micro'][k]*100)+' п.п. ['+fmt(c['ci'][0][k]*100)+'; '+fmt(c['ci'][1][k]*100)+']'
def main():
    r=get('results.json');p=r['summary'];me=p['arms'];hm=p['contrasts']['union_mask minus qwen_mask'];flat=p['contrasts']['union minus qwen'];flag=hm['ci'][0][1]>0
    sign='Преимущество подтвердилось по заранее определённому критерию.' if flag else 'Критерий подтверждения преимущества не выполнен.'
    t=['| Система | MSS@5 | MSS@8 | MSS@8, 2 048 | MSS, 2 048 только токены | MSS, 6 144 только токены | GroupRecall@5 | GroupRecall@8 |',
       '|---|---:|---:|---:|---:|---:|---:|---:|']
    for m,caption in [('qwen','Qwen3-Embedding-8B'),('union','Qwen с обученной поправкой'),('qwen_mask','Qwen с отсрочкой'),('union_mask','Qwen с поправкой и отсрочкой')]:
        w=me[m]['counts'];t.append('| '+caption+' | '+' | '.join([str(int(w[i])) for i in (0,1,2,7,8)]+[fmt(100*w[i]/101)+'%' for i in (4,5)])+' |')
    a0=me['union_mask']['counts'][1];b0=me['qwen_mask']['counts'][1];hyp=hm['repo_delta_primary'];ar=get('anchor.json')
    texts=[f"**{sign}** В 101 состоянии из 34 других репозиториев одноместный читатель с отсрочкой просмотренных фрагментов собрал полный набор среди первых восьми в **{int(a0)}/101** случаях, одиночный Qwen с той же отсрочкой — **{int(b0)}/101**. Парная разница **{interval(hm,1)}**. В {hm['wins'][1]} случаях полный набор появился, в {hm['loss'][1]} исчез. Состав выдачи из восьми фрагментов изменился в {hm['changed_set'][1]} состояниях. Макроразность при равном весе каждому репозиторию {fmt(100*hm['macro'][1])} п.п. [{fmt(100*hm['macroci'][0][1])}; {fmt(100*hm['macroci'][1][1])}]. [Протокол](PROTOCOL_RU.md) · [Все состояния и исходы](outcomes.json.gz)",
        "Исходный результат, который мотивировал проверку, составлял 131/204 против 114/204 на других 69 репозиториях (+8,33 п.п. [3,24; 13,49]). Сравниваемые регрессия, её вероятности на 101 состоянии и вес 0,65 заморожены до этого прогона. В подтверждении заново получили полный порядок Qwen для нового набора. Модель ранжирования обучалась на 179 состояниях из 68 других репозиториев. На обеих панелях сохраняется одинаковая индивидуальная стоимость фрагмента и одинаковый способ отложить просмотренное. [Результат, мотивировавший проверку](../facet_reader/REPORT_RU.md) · [Формула](../facet_reader/PROTOCOL_RU.md)",
        '\n'.join(t),
        f"В фиксированном режиме без отсрочки эффект при восьми фрагментах {interval(flat,1)}. Для пяти фрагментов с отсрочкой он равен {interval(hm,0)}, а при лимите только в 6 144 токена {interval(hm,8)}. Последний режим выдал в среднем {fmt(me['union_mask']['items'][5])} / {fmt(me['qwen_mask']['items'][5])} единицы и потратил {fmt(me['union_mask']['tokens'][5])} / {fmt(me['qwen_mask']['tokens'][5])} токена. Разрез по целым репозиториям с положительным / отрицательным / нулевым балансом состояний составляет {sum(v['net']>0 for v in hyp.values())} / {sum(v['net']<0 for v in hyp.values())} / {sum(v['net']==0 for v in hyp.values())}. Дополнительные интервалы приводятся без поправки на множественность. [Числа и интервалы](results.json)",
        f"Выполнено локальное GPU-ранжирование {r['all_ranked']:,} кандидатных записей. Время измеренных 101 кодирований {fmt(r['embedding_seconds']/60)} мин, входных токенов {r['input_tokens']:,}. Qwen3-Embedding-8B Q4_K_M отработала на RTX 3090. Одно повторно закодированное контрольное состояние R45 имело те же длины и top‑8, максимальное абсолютное расхождение косинусных оценок — {ar['max_abs_cosine_delta']:.3g}. Контроль не входит в 101 оценённое состояние. Эталонная функция SERBench сверена для {r['native_prefixes']} префиксов. [Контроль аппаратного повтора](anchor.json) · [Воспроизведение](REPRODUCE_RU.md)",
        "Обобщение ограничено публичным Cal500. В этой новой связке Qwen не измерялась ранее на 101 состоянии. Иные методы уже сравнивались на них, в том числе R47 с BM25, и направление следующей гипотезы выбрано по результатам предыдущей панели. Отложенные репозитории дают отдельную проверку переносимости при фиксированных параметрах. Эксперимент измеряет чтение памяти из кандидатного пула в зафиксированном состоянии. Обновление графа во времени и успешность решения задачи требуют отдельных экспериментов. Результат на закрытом Test500 и сравнение с официальным лидером остаются открытыми. [Открытая часть SERBench](https://github.com/LordTARN1SHED/SERBench/blob/8c27a88e48dcbcd4a5745573c95937a4740f4406/docs/REPRODUCTION.md)"]
    text='# Проверка одноместного читателя на других репозиториях\n\n'+'\n\n'.join(texts)+'\n'
    (D/'REPORT_RU.md').write_text(text,encoding='utf8')
if __name__=='__main__':main()

